$$\begin{aligned}
&\text{① 函数平均值（数一/二/三公共）：}\;\bar{y}=\frac{1}{b-a}\int_a^b y(x)\,\mathrm{d}x\quad\bigl(\text{由积分中值定理知 }\bar{y}=y(\xi),\;\xi\in[a,b]\bigr)\\
&\text{② 均匀曲边梯形形心（仅数一、数二）：}\;\bar{x}=\frac{\displaystyle\iint_D x\,\mathrm{d}\sigma}{\displaystyle\iint_D\mathrm{d}\sigma}=\frac{\displaystyle\int_a^b x f(x)\,\mathrm{d}x}{\displaystyle\int_a^b f(x)\,\mathrm{d}x},\qquad \bar{y}=\frac{\displaystyle\iint_D y\,\mathrm{d}\sigma}{\displaystyle\iint_D\mathrm{d}\sigma}=\frac{\displaystyle\frac{1}{2}\int_a^b f^2(x)\,\mathrm{d}x}{\displaystyle\int_a^b f(x)\,\mathrm{d}x}
\end{aligned}$$
